{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "VPC flow logs are not enabled, which means network traffic within the VPC cannot be monitored. This can hinder incident investigation and security analysis."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Ensure the default security group of every VPC restricts all traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The default security group for the VPC allows unrestricted traffic, which can expose resources to unauthorized access."
    }
  ],
  "patched_code": "resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"

  enable_dns_support   = true
  enable_dns_hostnames = true

  flow_log {
    traffic_type = "ALL"
    log_destination_type = "cloud-watch-logs"
    log_group_name = "vpc-flow-logs"
    iam_role_arn = aws_iam_role.vpc_flow_logs_role.arn
  }
}

resource "aws_iam_role" "vpc_flow_logs_role" {
  name = "vpc-flow-logs-role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "vpc-flow-logs.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

resource "aws_security_group" "default_restrictive" {
  name        = "default-restrictive-sg"
  description = "Restricts all traffic"
  vpc_id      = aws_vpc.changeme_aws_vpc_simple.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }
}
",
  "fix_summary": "Enabled VPC flow logs to monitor network traffic and added a restrictive default security group to block all ingress and egress traffic by default."
}
